SELECT * FROM (SELECT 'RH:' || material_id event_id, material_id case_id, 'Reheating Started' activity, furnace_charged_at timestamp FROM as_rolled_material WHERE furnace_charged_at IS NOT NULL UNION ALL SELECT 'CS:' || material_id event_id, material_id case_id, 'Crop Shear Passed' activity, crop_shear_passed_at timestamp FROM as_rolled_material WHERE crop_shear_passed_at IS NOT NULL UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Rolling Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='RL') ORDER BY case_id,timestamp,event_id;
